<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted} from 'vue';
import {ElMessage} from 'element-plus';
import {message} from '../api';
import {money,date,ton,download} from '../fulfillment';
const props=defineProps<{task:any,client:any}>(),emit=defineEmits(['changed']);
const busy=ref(false),error=ref(''),tab=ref('business'),fees=ref<any[]>([]),vehicleCapacityKg=ref<number|null>(null);
const capacity=computed(()=>Math.max(.1,(vehicleCapacityKg.value||0)/1000));
const locked=computed(()=>['COMPLETED','CANCELLED'].includes(props.task.status));
const business=reactive<any>({quantity:undefined,receiver:'',sealNo:'',weightTicketNo:'',gross:undefined,tare:undefined,note:'',containers:[]});
const fee=reactive<any>({feeCode:'SHIP_RELEASE',amount:0,description:'',evidenceId:'',requestKey:crypto.randomUUID()});
function sync(){const f=props.task.feedback||{};Object.assign(business,{quantity:f.quantityKg>0?f.quantityKg/1000:undefined,receiver:f.receiver||'',sealNo:f.sealNo||'',weightTicketNo:f.weightTicketNo||'',gross:f.grossKg==null?undefined:f.grossKg/1000,tare:f.tareKg==null?undefined:f.tareKg/1000,note:f.note||'',containers:(f.containers?.length?f.containers:props.task.boxNo?[{boxNo:props.task.boxNo,quantityKg:f.quantityKg}]:props.task.containerized&&!locked.value?[{boxNo:'',quantityKg:undefined}]:[]).map((v:any)=>({boxNo:v.boxNo,quantity:v.quantityKg>0?v.quantityKg/1000:undefined}))});}
async function load(){try{const data=(await props.client.get('/driver/tasks/'+props.task.id+'/service')).data.data;fees.value=data.fees;vehicleCapacityKg.value=data.task.vehicleCapacityKg>0?data.task.vehicleCapacityKg:null;if(vehicleCapacityKg.value==null)error.value='车辆核定载重尚未登记，请联系物流运营商核实车辆档案';}catch(e){error.value=message(e);}}
watch(()=>[props.task.id,props.task.feedbackSubmittedAt],sync,{immediate:true});
watch(()=>props.task.version,load);onMounted(load);
watch(()=>[business.gross,business.tare],()=>{business.quantity=business.gross!=null&&business.tare!=null&&business.gross>business.tare?Math.round((business.gross-business.tare)*10)/10:undefined;});
async function upload(e:Event,category:string){const input=e.target as HTMLInputElement,f=input.files?.[0];if(!f)return;busy.value=true;error.value='';try{const data=new FormData();data.append('file',f);const result=(await props.client.post('/driver/tasks/'+props.task.id+'/evidence?category='+category,data)).data.data;if(category==='FEE')fee.evidenceId=result.id;emit('changed');ElMessage.success('已上传');}catch(e){error.value=message(e);}finally{busy.value=false;input.value='';}}
async function file(f:any){try{const r=await props.client.get('/driver/evidence/'+f.id,{responseType:'blob'});download(r.data,f.name,f.mime);}catch(e){error.value=message(e);}}
async function report(){if(vehicleCapacityKg.value==null){error.value='车辆核定载重尚未登记，请联系物流运营商核实车辆档案';return;}if(!business.quantity||business.quantity>capacity.value){error.value='实际净重须大于零且不能超过车辆核定载重';return;}if(props.task.containerized&&(!business.containers.length||business.containers.some((c:any)=>!c.boxNo||!c.quantity))){error.value='请填写每个集装箱的箱号与实际粮食数量';return;}if(props.task.containerized&&business.containers.reduce((n:number,c:any)=>n+Math.round(c.quantity*1000),0)!==Math.round(business.quantity*1000)){error.value='每箱粮食数量合计须等于磅单净重';return;}if((!business.weightTicketNo||business.gross==null||business.tare==null)){error.value='请填写磅单号、毛重和皮重';return;}if(!business.receiver.trim()){error.value='请填写签收人';return;}busy.value=true;error.value='';try{await props.client.post('/driver/tasks/'+props.task.id+'/feedback',{version:props.task.version,quantityKg:Math.round(business.quantity*1000),receiver:business.receiver,sealNo:business.sealNo,weightTicketNo:business.weightTicketNo,grossKg:business.gross==null?undefined:Math.round(business.gross*1000),tareKg:business.tare==null?undefined:Math.round(business.tare*1000),note:business.note,containers:props.task.containerized?business.containers.map((v:any)=>({boxNo:v.boxNo.trim().toUpperCase(),quantityKg:Math.round(v.quantity*1000)})):[]});emit('changed');ElMessage.success('业务信息已回传，等待运营商确认阶段完成');}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function addFee(){if(!fee.amount||fee.feeCode==='OTHER'&&!fee.description.trim()){error.value='请填写费用金额，其他杂费须填写具体说明';return;}busy.value=true;error.value='';try{await props.client.post('/driver/tasks/'+props.task.id+'/fees',{feeCode:fee.feeCode,amountCents:Math.round(fee.amount*100),description:fee.description,evidenceId:fee.evidenceId||undefined,requestKey:fee.requestKey});Object.assign(fee,{amount:0,description:'',evidenceId:'',requestKey:crypto.randomUUID()});await load();ElMessage.success('账单信息已回传');}catch(e){error.value=message(e);}finally{busy.value=false;}}
</script>
<template><section class="driver-feedback"><div class="task-reference"><strong>{{task.waybillNo}}</strong><span>{{task.segment.origin}} → {{task.segment.destination}}</span><small>{{task.cargo}} · {{task.feedbackSubmittedAt||task.unloadedKg>0?ton(task.unloadedKg||task.feedback?.quantityKg||0):'待过磅'}} · {{task.containerized?'集装箱':'散货'}}</small></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="feedback-tabs"><button :class="{active:tab==='business'}" @click="tab='business'">业务信息</button><button :class="{active:tab==='fees'}" @click="tab='fees'">账单信息</button></div><template v-if="tab==='business'"><p v-if="task.feedbackSubmittedAt" class="feedback-status">已于 {{date(task.feedbackSubmittedAt)}} 回传{{locked?' · 阶段已完成':' · 等待运营商确认'}}</p><el-form label-position="top" :disabled="locked||busy||vehicleCapacityKg==null"><template v-if="task.containerized"><div class="container-feedback"><header><b>集装箱与粮食数量</b><el-button link :disabled="business.containers.length>=10" @click="business.containers.push({boxNo:'',quantity:undefined})">添加箱号</el-button></header><div v-for="(c,i) in business.containers" :key="i"><el-form-item label="箱号" required><el-input v-model="c.boxNo" :aria-label="'回传箱号 '+(Number(i)+1)" maxlength="11"/></el-form-item><el-form-item label="本箱粮食（吨）" required><el-input-number v-model="c.quantity" :min="0.1" :max="capacity" :precision="1" :step=".1" :aria-label="'本箱粮食数量 '+(Number(i)+1)"/></el-form-item><el-button link type="danger" @click="business.containers.splice(Number(i),1)">移除</el-button></div></div><el-form-item label="设备交接单" required><label class="driver-upload"><input type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="locked||busy" @change="(e:Event)=>upload(e,'EIR')"/>上传设备交接单</label></el-form-item><el-form-item label="铅封号" required><el-input v-model="business.sealNo" aria-label="铅封号"/></el-form-item></template><template><el-form-item label="磅单" required><label class="driver-upload"><input type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="locked||busy" @change="(e:Event)=>upload(e,'WEIGH')"/>上传磅单</label></el-form-item><el-form-item label="磅单号" required><el-input v-model="business.weightTicketNo" aria-label="回传磅单号"/></el-form-item><div class="weight-grid"><el-form-item label="毛重（吨）" required><el-input-number v-model="business.gross" :min="0.1" :precision="1" :step=".1" aria-label="回传磅单毛重"/></el-form-item><el-form-item label="皮重（吨）" required><el-input-number v-model="business.tare" :min="0" :precision="1" :step=".1" aria-label="回传磅单皮重"/></el-form-item></div></template><el-form-item label="签收单" required><label class="driver-upload"><input type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="locked||busy" @change="(e:Event)=>upload(e,'RECEIPT')"/>上传签收单</label></el-form-item><el-form-item label="实际签收数量（吨）" required><el-input-number v-model="business.quantity" disabled :min="0.1" :max="capacity" :precision="1" :step=".1"/></el-form-item><p class="quantity-basis">实际签收数量由磅单毛重减皮重计算；核定载重 {{vehicleCapacityKg==null?'待核实':ton(vehicleCapacityKg)}}。</p><el-form-item label="签收人" required><el-input v-model="business.receiver" aria-label="签收人"/></el-form-item><el-form-item label="运输说明（选填）"><el-input v-model="business.note" type="textarea" :rows="2" maxlength="2000"/></el-form-item><el-button v-if="!locked" type="primary" class="driver-submit" :loading="busy" @click="report">回传业务信息</el-button></el-form></template><template v-else><article v-for="f in fees" :key="f.id" class="driver-fee"><header><b>{{f.name}}</b><strong>{{money(f.amountCents)}}</strong></header><p>{{f.description||'—'}}</p><small>{{f.billId?'已计入运单账单':'待运营商汇总'}}</small></article><el-empty v-if="!fees.length" description="暂无回传费用" :image-size="40"/><el-form v-if="!locked" label-position="top"><el-form-item label="费用项目"><el-select v-model="fee.feeCode"><el-option label="船公司放单费" value="SHIP_RELEASE"/><el-option label="港口杂项作业费" value="PORT_MISC"/><el-option label="清箱费" value="CLEAN_BOX"/><el-option label="其他杂费" value="OTHER"/></el-select></el-form-item><el-form-item label="金额（元）" required><el-input-number v-model="fee.amount" :min="0" :max="1000000" :precision="2"/></el-form-item><el-form-item :label="fee.feeCode==='OTHER'?'具体说明（必填）':'费用说明'"><el-input v-model="fee.description" type="textarea" :rows="2" maxlength="2000"/></el-form-item><el-form-item label="费用凭证"><label class="driver-upload"><input type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="busy" @change="(e:Event)=>upload(e,'FEE')"/>上传费用凭证</label><small v-if="fee.evidenceId">已关联凭证</small></el-form-item><el-button type="primary" class="driver-submit" :loading="busy" @click="addFee">回传账单信息</el-button></el-form></template><h3>已上传单据</h3><button v-for="f in task.evidence.filter((f:any)=>tab==='fees'?f.category==='FEE':f.category!=='FEE')" :key="f.id" class="driver-document" @click="file(f)">{{f.category==='EIR'?'交接单':f.category==='WEIGH'?'磅单':f.category==='RECEIPT'?'签收单':'凭证'}} · {{f.name}} ↗</button></section></template>
<style scoped>.driver-feedback{padding:16px;background:#fff;border-radius:12px}.task-reference{display:flex;flex-direction:column;gap:9px;font-size:13px}.task-reference strong{font-size:12px;color:#617397}.task-reference small{color:#7c8eab}.feedback-tabs{display:flex;margin:20px 0 16px;border-bottom:1px solid #e6edf8}.feedback-tabs button{flex:1;background:none;border:0;font-size:14px;color:#8594ad;padding:12px;cursor:pointer}.feedback-tabs .active{color:#087aff;border-bottom:2px solid #087aff;font-weight:600}.driver-feedback :deep(.el-form-item__label){font-size:12px;color:#687d9d}.driver-feedback :deep(.el-select),.driver-feedback :deep(.el-input-number){width:100%}.weight-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.driver-upload{display:inline-flex;color:#087aff;border:1px solid #bbd9ff;border-radius:5px;font-size:12px;padding:7px 12px;cursor:pointer}.driver-upload input{position:absolute;opacity:0;width:1px;height:1px}.driver-upload:focus-within{outline:2px solid #087aff;outline-offset:2px}.driver-submit{width:100%;margin:6px 0 16px}.feedback-status{font-size:11px;color:#548a73;background:#f0faf4;padding:10px;border-radius:6px}.driver-fee{padding:12px;background:#f5f8fe;border-radius:7px;margin-bottom:10px}.driver-fee header{display:flex;justify-content:space-between;font-size:12px}.driver-fee header strong{color:#087aff}.driver-fee p,.driver-fee small{font-size:11px;color:#8595ae}.driver-document{display:block;max-width:100%;border:0;background:#f5f8fe;padding:10px 12px;border-radius:5px;color:#4476b8;font-size:11px;margin:6px 0;cursor:pointer;text-align:left}h3{font-size:12px;color:#687d9d;margin:16px 0 10px}</style>

<style scoped>.container-feedback{margin:14px 0;background:#f5f8fe;padding:12px;border-radius:8px}.container-feedback header{display:flex;align-items:center;justify-content:space-between;font-size:12px}.container-feedback>div{border-top:1px solid #e6edf7;padding-top:12px;margin-top:8px}.quantity-basis{font-size:11px;line-height:1.7;color:#8595ae;margin:-8px 0 16px}</style>
